# Validate before Load so an invalid body is a 400, not masked by a 404.
validate:
  class: net.officefloor.hq.app.claim.ValidateWaive
  next: snapshot
# The sheet's figures before the change, so the change can audit what it moved.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyWaive
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveWaive
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimWaived
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

/** Body of POST /api/sheets/{sheetId}/claims/{claimId}/waive: who waives the claim's late charge. */
public record WaiveRequest(String user) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.PathVariable;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;

public class ValidateWaive {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody WaiveRequest request, Out<WaiveRequest> body, Settings settings)
            throws ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        body.set(request);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Val;

/** Waives the late charge of an OPEN or PENDING claim; only a steward waives, and a claim only once. */
public class ApplyWaive {
    public void apply(@Val WaiveRequest request, @Val Claim claim, Settings settings) throws ClaimStatusRefusedException {
        if (!Settings.STEWARD.equals(settings.role(claim.getSheetId(), request.user()))) {
            throw new ClaimStatusRefusedException("Only a steward can waive a claim's late charge");
        }
        if (!claim.getStatus().isOpen()) {
            throw new ClaimStatusRefusedException("Only an OPEN or PENDING claim's late charge can be waived");
        }
        if (claim.isWaived()) {
            throw new ClaimStatusRefusedException("The claim's late charge is already waived");
        }
        claim.setWaived(true);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

public class SaveWaive {
    public void save(@Val Claim claim, Claims claims) {
        claims.waive(claim);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
