import { asString, useSearchParam } from '../../url/useSearchParam';
import { formatCents, showDue } from '../rates/due';
import { crewDueCents, useCrews } from '../crews/useCrews';
import { STATUSES, useSheetFigures } from '../people/useSheetFigures';

// The sheet's counters, always on show: its people (retired included), its claims per status (as
// the summary counts them) and its due-total and overdue-total (as the sheet's totals show them).
// Then the signed-in user's own figures: the due-total and overdue-total of the person on the sheet
// with the user's name or alias (case and outer spaces ignored); nothing when there is no such person.
// And the user's crew total: the due-totals of the crews that person leads, added up; nothing when
// they lead none.
export function SheetHeader() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const { people, byId, sheetDueTotal, sheetOverdueTotal, statusCount, totalOf, overdue, overdueTotal } = useSheetFigures(sheet);
  const crews = useCrews(sheet);
  const key = (name: string) => name.trim().toLowerCase();
  const me = user === '' ? undefined : people.find((p) => [p.name, ...p.aliases].some((n) => key(n) === key(user)));
  const led = me ? crews.filter((c) => c.leadId === me.id) : [];
  const crewTotal = led.length === 0 ? '' : formatCents(led.reduce((sum, c) => sum + crewDueCents(c, byId, totalOf), 0n));
  return (
    <header data-testid="header">
      People: <span data-testid="header-people-count">{people.length}</span>
      {STATUSES.map((s) => (
        <span key={s}>
          {' · '}
          {s}: <span data-testid={`header-claims-${s}-count`}>{statusCount(s)}</span>
        </span>
      ))}
      {' · '}Due: <span data-testid="header-due-total">{sheetDueTotal}</span>
      {' · '}Overdue: <span data-testid="header-overdue-total">{sheetOverdueTotal}</span>
      {' · '}Mine: due <span data-testid="my-due-total">{me ? showDue(totalOf(me)) : ''}</span>
      {', '}overdue <span data-testid="my-overdue-total">{me ? overdueTotal(overdue.filter((c) => c.personId === me.id)) : ''}</span>
      {', '}crew due <span data-testid="my-crew-due-total">{crewTotal}</span>
    </header>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { readPath, useAsOf } from '../asof/useAsOf';

export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED' | 'REVIEW';

/** A claim; `amount` is shown with two decimals ("10.25"); `number` is the one given when it was
 *  opened (a voided claim keeps it), "" for a draft; `due` is the due fixed when it was settled, else the
 *  figure the person's last statement bound it to, "" while its due is live (worked from the current
 *  rate) or bound to n/a; `stated` is whether the last statement bound it. A claim with a negative
 *  amount is a correction: its due has no floor and no late charge. */
export type Claim = {
  id: string;
  personId: string;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string;
  due: string;
  /** The user who opened the claim, "" if it was never opened. */
  openedBy: string;
  stated: boolean;
  /** The number of the SETTLED claim a correction (a negative amount) corrects, "" for any other claim. */
  corrects: string;
  /** The claim's external reference, unique on the sheet regardless of case; "" for none. */
  ref: string;
  /** The claim's tags, lower-cased, sorted and comma separated ("a,b"); "" for none. */
  tags?: string;
  /** The date the claim's rounding goes by: a correction's is the date of the claim it corrects. */
  roundingDate: string;
  /** The claim's due-by, fixed when it was created: its date plus the first of its person's own terms, their grade's terms and the sheet's terms in force on that date. */
  dueBy: string;
  /** The claim's status log, oldest first: "<STATUS> by <user> on <date> due=<due>" per status it has had. */
  log: string[];
  /** Whether a steward has waived the claim's late charge: it bears none from then on, whatever its overdue state. */
  waived?: boolean;
  /** Whether the claim is held: it still counts in every total. */
  held?: boolean;
  /** The date the claim was last deferred until, "" if it was never deferred. */
  deferredUntil: string;
  /** The claim's proofs count. */
  proofs: string;
  /** How many of the claim's proofs are receipts. */
  proofReceipts?: string;
  /** How many of the claim's proofs are photos. */
  proofPhotos?: string;
  /** The number of the claim a split made this claim from, "" for any other claim. */
  splitFrom: string;
  /** The user whose open editor locks the claim for everyone else, "" when unlocked. */
  lockedBy?: string;
  /** Whether the claim was added while its period was soft-closed. */
  lateEntry?: boolean;
  /** The last day (the sheet's today then) a reminder was written for the claim, "" if never. */
